                              type: "equation",
                              body: "\\begin{gathered}\n            \\ip{\\vb{v}_i}{\\vb{v}_j} = \\delta_{ij} \\\\\n            \\ip{\\vb{a}_i}{\\vb{a}_j} = \\delta_{ij}\n          \\end{gathered}",
